"""Guest stdlib DATA audit of assigned public cache/toolchain source only."""
import hashlib,json,os,pathlib,stat,tarfile,tomllib
job=pathlib.Path('/Volumes/ZeroPWBuild/required-generations-r1-8ca2cf0')
assert os.getuid()==501
for name in ['home','control','evidence','target','cargo-home','txxx']:
 st=(job/name).stat();assert st.st_uid==501 and stat.S_IMODE(st.st_mode)==0o700,(name,st.st_uid,stat.S_IMODE(st.st_mode))
assert len(os.environ['TMPDIR'].encode('ascii'))==57
home=job/'cargo-home';reg=home/'registry';lock=tomllib.loads((job/'src/rust/Cargo.lock').read_text())
expected={(p['name'],p['version']):p.get('checksum') for p in lock['package'] if p.get('source','').startswith('registry+')}
archives=sorted((reg/'cache').rglob('*.crate'));count=0;inventory={};archive_inventory={}
for p in archives:
 data=p.read_bytes();h=hashlib.sha256(data).hexdigest();name=p.stem
 candidates=[(n,v) for n,v in expected if name==n+'-'+v];assert len(candidates)==1,(name,candidates);assert expected[candidates[0]]==h
 dirs=list((reg/'src').glob('*/'+name));assert len(dirs)==1,name;src=dirs[0]
 meta=json.loads((src/'.cargo-checksum.json').read_text());assert meta['package']==h
 with tarfile.open(p,'r:gz') as tf:
  for member in tf:
   if member.isdir():continue
   assert member.isfile(),member.name
   path=pathlib.PurePosixPath(member.name);assert path.parts[0]==name and '..' not in path.parts
   f=src.joinpath(*path.parts[1:]);assert f.is_file() and not f.is_symlink();raw=f.read_bytes();assert raw==tf.extractfile(member).read(),member.name
   rel=f.relative_to(reg).as_posix();st=f.stat();inventory[rel]={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'mode':stat.S_IMODE(st.st_mode)};count+=1
 for rel,hf in meta['files'].items():
  path=pathlib.PurePosixPath(rel);assert not path.is_absolute() and '..' not in path.parts
  assert hashlib.sha256((src/rel).read_bytes()).hexdigest()==hf
 archive_inventory[p.relative_to(reg).as_posix()]={'sha256':h,'bytes':len(data),'mode':stat.S_IMODE(p.stat().st_mode)}
assert len(archives)==172 and count==8194,(len(archives),count)
# Metadata created by Cargo is public cache bookkeeping, recorded separately.
source_extra={}
for p in (reg/'src').rglob('*'):
 if p.is_file():
  n=p.relative_to(reg).as_posix()
  if n not in inventory:source_extra[n]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'mode':stat.S_IMODE(p.stat().st_mode)}
print(json.dumps({'uid':os.getuid(),'archives':len(archives),'source_files':count,'archives_lock_tar_source_metadata':'MATCH','archive_inventory':archive_inventory,'source_inventory':inventory,'extra_public_bookkeeping':source_extra},sort_keys=True))

