"""Assigned-job-only stdlib metadata/cleanup, after all product commands finish."""
import json,os,pathlib,platform,shutil,stat,subprocess
job=pathlib.Path('/Volumes/ZeroPWBuild/required-generations-r1-8ca2cf0');tmp=job/'txxx';assert os.getuid()==501 and len(str(tmp).encode('ascii'))==57
roots={}
for name in ['home','control','evidence','target','cargo-home','txxx']:
 p=job/name;s=p.lstat();assert stat.S_ISDIR(s.st_mode) and s.st_uid==501 and stat.S_IMODE(s.st_mode)==0o700
 roots[name]={'uid':s.st_uid,'mode':oct(stat.S_IMODE(s.st_mode))}
left=[]
for p in sorted(tmp.rglob('*')):
 s=p.lstat();assert s.st_uid==501;assert not stat.S_ISLNK(s.st_mode)
 assert stat.S_ISDIR(s.st_mode) or stat.S_ISREG(s.st_mode),('unexpected scratch type',p.relative_to(tmp).as_posix())
 left.append({'path':p.relative_to(tmp).as_posix(),'uid':s.st_uid,'mode':oct(stat.S_IMODE(s.st_mode)),'type':'directory' if p.is_dir() else 'regular','bytes':s.st_size if p.is_file() else None})
# Only the fresh task's assigned synthetic scratch is eligible. No file contents
# are read or exported; source/evidence/HOME/cache/target and old jobs remain.
for p in list(tmp.iterdir()):
 if p.is_dir():shutil.rmtree(p)
 else:p.unlink()
assert not list(tmp.iterdir())
versions={}
for name in ['rustc','cargo']:
 r=subprocess.run(['/opt/homebrew/bin/'+name,'--version'],stdin=subprocess.DEVNULL,capture_output=True,check=True,timeout=10);versions[name]=r.stdout.decode().strip()
v=os.statvfs(job)
print(json.dumps({'uid':os.getuid(),'system':os.uname().sysname,'machine':os.uname().machine,'mac_version':platform.mac_ver()[0],'cpu_count':os.cpu_count(),'python':platform.python_version(),'versions':versions,'private_roots':roots,'tmpdir_ascii_bytes':57,'scratch_before_metadata':left,'scratch_after_entries':0,'scratch_cleanup_scope':'assigned fresh task TMP only; metadata only, no contents exported','job_volume_available_bytes':v.f_bavail*v.f_frsize,'physical_acceptance':'NOTRUN; virtual environment per assignment; no whole-machine-idle claim'},sort_keys=True))
